    {"input": "Order 9 never arrived, I want a human", "tool": "escalate", "arg": "9"},
]

def as_text(candidate):
    if isinstance(candidate, dict):
        return "\n\n".join(str(v) for v in candidate.values())
    return str(candidate)

def call_model(system, user):
    body = json.dumps({"model": "claude-haiku-4-5", "max_tokens": 100, "temperature": 0, "system": system, "messages": [{"role": "user", "content": user}]}).encode()
    req = urllib.request.Request("https://api.anthropic.com/v1/messages", data=body, headers={"x-api-key": os.environ.get("ANTHROPIC_API_KEY", ""), "anthropic-version": "2023-06-01", "content-type": "application/json"})
    with urllib.request.urlopen(req, timeout=40) as r:
        data = json.load(r)
    return "".join(b.get("text", "") for b in data.get("content", []))

def score_one(system, ex):
    try:
        raw = call_model(system, ex["input"])
    except Exception as err:
        return 0.0, {"input": ex["input"], "error": "model call failed: " + repr(err)}
    try:
        m = re.search(r"\{.*\}", raw, re.S)
        parsed = json.loads(m.group(0))
        tool = str(parsed.get("tool", ""))
        arg = str(parsed.get("arg", ""))
    except Exception as err:
        return 0.0, {"input": ex["input"], "expected_tool": ex["tool"], "expected_arg": ex["arg"], "raw_output": raw, "error": "unparseable JSON: " + repr(err)}
    tool_ok = tool == ex["tool"]
    arg_ok = arg.strip() == str(ex["arg"])
    s = 0.0 if not tool_ok else (1.0 if arg_ok else 0.5)
    return s, {"input": ex["input"], "expected_tool": ex["tool"], "got_tool": tool, "expected_arg": ex["arg"], "got_arg": arg, "tool_correct": tool_ok, "arg_correct": arg_ok, "raw_output": raw}

def evaluate(candidate, example=None):
