    except Exception as err:
        return 0.0, {"error": repr(err)}
    if example is None:
        res = [score_one(system, ex) for ex in SAMPLE]
        return sum(s for s, _ in res) / len(res), {"cases": [i for _, i in res]}
    return score_one(system, example)
